// Declaração de Variáveis
const curso = "Desenvolvimento de Interfaces";
let aulaAtual = 15;
const totalAulas = 20;

// Arrow Function com Parâmetros e Retorno Implícito
const calcularProgresso = (atual, total) => ((atual / total) * 100).toFixed(0);

const porcentagem = calcularProgresso(aulaAtual, totalAulas);
console.log(`Progresso do aluno: ${porcentagem}%`);

// Estrutura Condicional
if (porcentagem >= 75) {
  console.log("Parabéns! Você está na reta final do curso.");
} else {
  console.log("Continue praticando para concluir as entregas.");
}
